# ---------------------------------------------------------------- line edits
def L(prefix, new, tag=""):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    if len(idx) != 1:
        raise SystemExit("[FAIL] line %s: expected 1, found %d :: %r"
                         % (tag or prefix[:40], len(idx), prefix[:70]))
    lines[idx[0]] = new
    N[0] += 1


L("# Endothelial-state remodeling",
  "# Endothelial-state composition in esophageal squamous cell carcinoma: reduced venous representation, tip-like enrichment, and a candidate interferon-responsive state")

L("Endothelial states in esophageal squamous cell carcinoma (ESCC) remain poorly resolved.",
  "Endothelial state composition in esophageal squamous cell carcinoma (ESCC) was re-examined in the CD45-negative compartment of GSE160269 (11,267 cells; 9,531 retained; 60 tumors, 4 adjacent non-malignant libraries). Nine marker-defined states were resolved. Because four tumors were paired with the four adjacent libraries, the primary comparison used the 56 unmatched tumors and four adjacent libraries with an exact two-sided Mann-Whitney test; the four pairs were reported as directions only and the pooled 60-versus-4 comparison as sensitivity. Differential expression used limma; ligand-receptor transcript abundance was assessed with CellChat on pooled cells. A tip-derived 23-gene score was evaluated in three bulk cohorts using nested, patient-grouped cross-validation in GSE53625 (179 pairs) and a non-refitted descriptive model in GSE20347 (17 pairs) and GSE45670 (28 tumors, 10 normals). In the primary comparison, the median venous fraction was 74.8% in adjacent mucosa versus 28.5% in tumors (BH q = 0.0005); tip-like endothelium rose from 0.2% to 14.8% (q = 0.0007), matrix-remodeling endothelium from 0 to 13.8% (q = 0.0005), and a candidate, exploratory interferon-responsive state from 0 to 4.6% (q = 0.0007). The venous Hodges-Lehmann shift was -44.8 percentage points (95% CI -61.2 to -28.7). Leave-one-adjacent-normal-out analyses preserved all 16 directions (joint BH q = 0.0010-0.0025). The interferon-responsive state was less stable: it appeared in one adjacent library (0.44%), survived correction in 16% and 85.5% of down-sampling replicates at 20 and 30 cells per sample, and showed inconsistent paired directions. CellChat gives a pooled transcript-level expression ranking, not tumour-specific communication or antigen presentation; MHC class I and MIF ranked highest. The score gave a nested cross-validated AUC of 0.9998 (95% CI 0.9993-1.0000) in GSE53625 and 1.000/0.989 in the two external cohorts, but matched random 23-gene sets reached almost identical values and the score was non-prognostic in GSE53625 (HR per SD 1.04, P = 0.686) and TCGA-ESCA. Seven matched pairs from two external cohorts supported the direction, but not the absolute proportions, of the compositional difference. These observations are descriptive, with no diagnostic or prognostic use.",
  "abstract")

L("Whether these states differ between tumors and paired adjacent mucosa in ESCC is unclear.",
  "Previous ESCC single-cell atlases have already compared endothelial populations between tumor and adjacent non-malignant tissue. The dataset re-analysed here resolved 42 cell types, including six endothelial subtypes, and reported that NEC1/2 were prevalent in adjacent tissue whereas TEC1-3 were restricted to tumors; it also related TEC proportions to regulatory and exhausted T-cell fractions [13]. A second ESCC atlas characterized immune and stromal heterogeneity [14], and a third resolved segment-specific endothelial subsets and a collagen/laminin angiogenic program in upper and lower ESCC [15]. What has not been done is a state-resolved re-analysis of the CD45-negative endothelial compartment that separates venous, tip-like, matrix-remodeling and interferon-responsive programs, together with a systematic assessment of how the four adjacent libraries, the paired design and the closure constraint affect the estimated differences. We therefore re-examined composition with a refined transcriptional-state framework, quantified robustness to sample imbalance and compositional bias, and tested the specificity and clinical limitations of a tip-derived expression score.",
  "intro3")

L("We returned to a published ESCC single-cell dataset whose authors had separated cells",
  "We returned to the published ESCC single-cell dataset whose authors separated cells into CD45-positive and CD45-negative fractions [13], isolated the endothelial compartment, and asked three questions. First, do the relative representations of these refined states differ between tumors and adjacent mucosa under a comparison that respects the paired structure of the libraries. Second, what transcriptional programs do the expanded states carry. Third, what immune-related transcript patterns accompany these states, and does a tumor-versus-adjacent expression score carry any specificity beyond generic differential expression.",
  "intro4")

L("Endothelial cells were down-sampled to at most 350 per state",
  "Endothelial cells were down-sampled to at most 350 per state, and 8,000 T cells were drawn at random from the T-cell matrix of GSE160269 (69,278 cells). T-cell states were assigned by marker detection: CD8 (CD8A or CD8B), CD4 (CD4 without CD8), regulatory (CD4 with FOXP3 and IL2RA), exhaustion-marker-high CD8 (CD8 with at least two of PDCD1, HAVCR2, LAG3, TIGIT and TOX), NK-like (no CD3D or CD3E but GNLY, NKG7 or KLRD1), and Other/unclassified T (no rule satisfied). The exhaustion-marker-high label denotes a transcriptional phenotype associated with multiple inhibitory receptors; it does not establish functional T-cell exhaustion [38]. Communication was inferred with CellChat v2 and CellChatDB.human using triMean and 50 permutations (50 was specified for this analysis; the default in the original method is 100) [23]. Robustness was re-run with 200 permutations under two independent endothelial down-sampling seeds. With 50 permutations the permutation P value has a resolution of 0.02 and 6,058 of the 6,132 retained pairs have P = 0; at 200 permutations in two robustness runs 5,990-6,034 of 6,132-6,144 pairs still had P = 0 and all survived Benjamini-Hochberg correction, with MHC class I, MIF and APP remaining the three leading pathways. The permutation test cannot discriminate among pairs, so we report the list as expressed ligand-receptor pairs; it does not support claims of statistical significance for individual pairs (Table S8). Interactions with fewer than ten cells per group were filtered out. Robustness of ligand-abundance ranks to endothelial down-sampling was checked with five random seeds (Table S8); in each seed the ranking B2M, HLA-B, HLA-A, HLA-C, CD74, PLVAP, HLA-E, PECAM1, CD99, APP, MIF, ICAM1 was identical. CellChatDB approximates the expression of a heteromeric complex by the geometric mean of its subunits, so a subunit with zero expression disables the complex; here ITGAL and ITGB2 are expressed by T cells and are essentially absent from endothelium (mean ITGB2 0.00), and adhesion ranks low because its ligand is far less abundant (mean UMI counts per cell: ICAM1 10.0) than the MHC class I ligands (HLA-A 33.6, HLA-B 37.5, B2M 108.6). T-cell labels were assigned by a single exclusive priority, so that each cell received exactly one label (NK-like > regulatory > exhaustion-marker-high CD8 > CD8 > CD4 T > Other/unclassified T). CD4- and CD8-double-positive cells received a CD8 label. Cells satisfying no rule were assigned to Other/unclassified T and excluded from the endothelial-to-T-cell summaries; of the 8,000 T cells, 885 were CD8 T, 2,937 exhaustion-marker-high CD8, 1,047 CD4 T, 833 Treg, 189 NK-like and 2,109 Other/unclassified T. Tumour-derived and adjacent-normal cells were pooled into one CellChat object; the analysis was not stratified by tissue of origin and patient identity was not used as a grouping factor. Because cells from different patients were combined, a ligand detected in one patient's endothelium and a receptor detected in another patient's T cells can contribute to the same model-inferred pair. The result is therefore a pooled transcript-level ligand-receptor expression landscape: it cannot be read as tumour-specific communication, as cell contact within one tissue microenvironment, or as a functional interaction.",
  "methods-cellchat")

L("All 69,278 T cells were assigned to five groups by marker detection",
  "All 69,278 T cells were assigned to five marker-detection groups (CD8, exhaustion-marker-high CD8, CD4, regulatory, NK-like), and the fraction of each group was computed per patient. Exhaustion was expressed as the proportion of exhaustion-marker-high cells among all CD8 T cells, so as not to confound it with CD8 abundance. This measure was correlated (Spearman) with the nine endothelial state fractions, and the analysis was repeated in samples with adequate cell numbers (at least 30 endothelial and 50 T cells). Spearman tests across the nine states were corrected with the Benjamini-Hochberg method; the 47-sample subset was defined post hoc from cell-number thresholds and is reported only as a sensitivity analysis. Unlike the exclusive labels used for CellChat, the marker-detection counts used for the patient-level correlation analysis were not mutually exclusive: exhaustion-marker-high CD8 cells are a subset of CD8 cells and regulatory cells a subset of CD4 cells, and a cell may contribute to more than one count. These overlapping counts were used only to compute patient-level fractions; the exhaustion variable was the proportion of CD8-positive cells carrying at least two exhaustion-associated markers, a transcriptional phenotype rather than a functional assay.",
  "methods-tcorr")

L("Unless stated otherwise, tests were two-sided and Benjamini-Hochberg correction",
  "Unless stated otherwise, tests were two-sided and Benjamini-Hochberg correction was applied within each pre-defined family. The primary tumor-versus-adjacent comparison used the 56 tumors without a paired adjacent library and the four adjacent non-malignant libraries; exact two-sided Mann-Whitney tests were applied to the nine state proportions, and the BH family was these nine tests. The four paired tumors (P126T, P127T, P128T and P130T, matched to P126N, P127N, P128N and P130N by sample identifier and by the 60-patient clinical table) were reported as paired directions only, without a P value. The pooled 60-versus-4 comparison was recomputed as a sensitivity analysis with the same nine-test family. Leave-one-adjacent-normal-out analyses comprised four deletions x four prespecified principal states = 16 exploratory comparisons; BH correction was applied jointly across these 16 tests and, separately, within each deletion across all nine states, and both are reported in Table S12. Because the four deletions are resamplings of one hypothesis rather than four independent hypotheses, the leave-one-out family is kept separate from the primary nine-test family. Other families were the nine-state correlations with T-cell exhaustion, the 9 x 5 analysis against the five original T-cell fractions, the six state proportions against each of three stage variables (six tests per variable), the retained CellChat pairs, and the Cox and Schoenfeld checks reported in Tables S8 and S10. Random-gene and permutation controls are empirical and were not corrected. Stage associations were tested only for the six states displayed in Figure 6 (tip, interferon-responsive, matrix-associated, venous, capillary and arterial); inflamed-venule, proliferating and lymphatic endothelium were not included, and the latter two comprised 329 and 34 cells, so this null result is a selective analysis. The four matched random-gene controls comprised 200 sets per pool (800 sets in total). All area-under-the-curve confidence intervals came from 2,000 bootstrap resamples at patient level; for the unpaired GSE45670 cohort each sample was resampled as its own cluster. The 581 CellChatDB.human entries that passed expression filtering and the 6,132 retained ligand-receptor pairs count different objects (database entries versus sender-receiver-resolved pairs). CellChat communication probability is a summed, dimensionless score across contributing pairs, not a probability, and can exceed one; in the figures it is labelled 'Aggregate CellChat score (arbitrary units)'. For the centered log-ratio analysis, zero counts were replaced by a 0.5 pseudo-count before re-closure. Dirichlet-multinomial null models drew per-sample probabilities from a Dirichlet distribution whose concentration was chosen by moment matching to the observed between-sample variance of the venous fraction (candidate grid 5, 20, 50, 100, 200, 400), then drew multinomial counts at each sample's observed cell total; 4,000 replicates were run per model and the empirical one-sided P value was computed as (1 + number of null coefficients at or below the observed value) / 4,001. Effect sizes for the primary 56-versus-4 comparison were estimated by the Hodges-Lehmann two-sample shift, with 95% confidence intervals from 2,000 patient-level bootstrap resamples. Closed-composition, CLR, Dirichlet-multinomial, cluster-retention and equal-cell-count down-sampling analyses were computed over all 60 tumors and four adjacent libraries as robustness checks on the original design; the primary P values and confidence intervals come from the 56-versus-4 comparison. Full tables are in Tables S11 and S12.",
  "methods-stats")

L("Analyses used R 4.4.3 (Seurat 5.5.0",
  "Analyses used R 4.4.3 (Seurat 5.5.0, harmony 1.2.4, limma 3.62.2, clusterProfiler 4.14.6, CellChat 2.2.0.9001, ComplexHeatmap 2.22.0, SingleR 2.8.0, celldex 1.16.0) and Python 3.13.14 (numpy 2.5.4, pandas 2.3.3, scipy 1.18.1, scikit-learn 1.9.1, statsmodels 0.15.0, lifelines 0.30.3, matplotlib 3.11.2). Full sessionInfo and the random-seed inventory are provided in Table S8. Analysis scripts are inventoried in Table S12 and are available from the corresponding author on reasonable request.",
  "methods-software")

L("The four normal samples contributed 856 endothelial cells",
  "The four adjacent non-malignant libraries contributed 856 endothelial cells, or 9.0% of the analyzed compartment; every tumor-adjacent comparison in this article rests on these four libraries. Four of the 60 tumors came from the same four patients. The primary comparison therefore used the 56 unmatched tumors; the four pairs are reported as directions and the pooled 60-versus-4 comparison as a sensitivity analysis (Table S12). This imbalance is inherent to the dataset and limits any comparison of states between tumor and adjacent tissue; we report those comparisons as exploratory.",
  "results-normal")

L("Proportions were recomputed as a closed composition",
  "Proportions were recomputed as a closed composition: the nine retained states sum to one in every sample, and states not detected were scored as zero. In the primary comparison of 56 unmatched tumors with four adjacent non-malignant libraries, the median venous fraction fell from 74.8% to 28.5% (exact Mann-Whitney P = 0.00011, BH q = 0.00050 across nine states; Figure 2B,C). Tip-like endothelium rose from 0.2% to 14.8% (P = 0.00029, q = 0.00066), matrix-remodeling endothelium from 0 to 13.8% (P = 0.000074, q = 0.00050), inflamed venule from 0 to 9.9% (q = 0.00065) and the candidate interferon-responsive state from 0 to 4.6% (P = 0.00039, q = 0.00069). Capillary endothelium fell from 11.6% to 6.1% (P = 0.046, q = 0.059) and was not significant after correction; arterial endothelium was unchanged (12.1% versus 13.4%, q = 0.62). Exact and asymptotic tests gave the same nine corrected judgements in this design (Table S12). The four paired tumors showed the venous direction in three of four pairs (tumor minus adjacent: +23.1, -5.0, -19.6 and -89.5 percentage points), the tip-like direction in two of four, and the interferon-responsive direction in two of four; no P value is attached to these pairs. The four adjacent libraries gave venous fractions of 57.1%, 72.7%, 76.9% and 89.5% (56, 264, 308 and 228 endothelial cells). Removing each adjacent library in turn preserved the direction of all 16 prespecified comparisons and all 16 joint-BH judgements (q = 0.0010-0.0025). The median tumour-minus-adjacent difference was -46.4 percentage points for venous endothelium (Hodges-Lehmann -44.8, bootstrap 95% CI -61.2 to -28.7), +14.7 for tip-like cells (8.6 to 17.0), +13.8 for matrix-remodeling endothelium (10.4 to 15.1) and +4.6 for the interferon-responsive state (3.2 to 6.4). The pooled 60-versus-4 sensitivity analysis gave the same directions and all principal judgements, but capillary endothelium crossed the 0.05 boundary (exact q = 0.049), as it did when the 529-cell fibroblast-like cluster was retained (q = 0.048); capillary is therefore a boundary result, not a stable finding. Full tables are in Tables S11 and S12.",
  "results-composition")

L("Individual tumors varied widely (Figure 2A).",
  "Individual tumors varied widely (Figure 2A). Tip-cell fractions ranged from 0 to 60%, and the interferon-responsive state was undetectable in 6 of 60 tumors (10%). Its stability was lower than that of the venous and tip-like differences: it appeared in only one adjacent library, survived correction in 16% and 85.5% of equal-cell-count down-sampling replicates at 20 and 30 cells per sample, showed inconsistent directions in the four paired libraries, and had opposite marker-level support in GSE203067. We therefore treat it as a candidate, exploratory state rather than a validated endothelial subtype (Tables S9, S11, S12).",
  "results-variability")

L("### An interferon-responsive subset is largely tumor-specific",
  "### A candidate interferon-responsive state is largely tumor-restricted")

L("The interferon-responsive state expressed CXCL9",
  "The interferon-responsive state expressed CXCL9, CXCL10 and CXCL11 together with RSAD2 and IFIT2 (Figure 4A). Its median fraction was 4.6% in the 56 unmatched tumors versus 0 in adjacent mucosa; only one of the four adjacent libraries contained any cells of this state (0.44%). This state is labelled 'interferon-responsive' because these transcripts do not distinguish type I from type II interferon signaling; the label is descriptive and does not establish an activated state or a functionally distinct endothelial lineage.",
  "results-ifn")

L("Across the 60 tumors, the fraction of interferon-responsive endothelium",
  "Across all 60 tumors, in a descriptive analysis separate from the primary paired design, the fraction of interferon-responsive endothelium correlated nominally with the proportion of CD8 T cells carrying at least two exhaustion-associated markers (rho = 0.28, P = 0.029), but not with total CD8 abundance; after Benjamini-Hochberg correction across the nine states the smallest FDR was 0.16, so no state was significant. Arterial endothelium gave a similar coefficient (rho = 0.27, P = 0.036) and tip cells did not (rho = 0.15, P = 0.26). In a post hoc subset of 47 tumors with adequate cell numbers (at least 30 endothelial and 50 T cells) the association was stronger (rho = 0.47, P = 0.0009, FDR = 0.008; Figure S2); because this subset was defined after seeing the data, we report it as a sensitivity analysis only. The corresponding 9 x 5 analysis against the five original T-cell fractions gave a minimum FDR of 0.39 (Table S8).",
  "results-corr")

L("### A pooled ligand-receptor expression landscape ranks MHC class I and MIF highest",
  "### A pooled transcript-level ligand-receptor expression landscape")

L("CellChat was run on 10,813 cells",
  "CellChat was run on 10,813 cells (2,813 endothelial, 8,000 T) and 581 database ligand-receptor entries, which expanded to 6,132 sender-receiver-resolved ligand-receptor pairs retained after filtering; 1,556 of these connected an endothelial state to one of the five interpretable T-cell groups. The 2,109 T cells satisfying no marker rule were labelled Other/unclassified T and excluded from these endothelial-to-T-cell summaries. Endothelial states had the largest number of retained pairs directed to exhaustion-marker-high CD8 cells (Figure 5A). Raising the permutation number to 200 under two down-sampling seeds left MHC class I, MIF and APP as the three leading pathways (Table S8). Because tumour-derived and adjacent-normal cells, and cells from different patients, were pooled in one object, this ranking is a pooled transcript-level expression landscape: it does not identify tumour-specific endothelial-to-T-cell interactions or require that a ligand and its receptor were present in the same patient or tissue microenvironment.",
  "results-cellchat1")

L("The dominant pathways were MHC class I",
  "The dominant pathways were MHC class I (aggregate CellChat score 32.3 arbitrary units, 180 retained pairs) and MIF (13.7, 80 pairs), followed by APP (9.6), collagen (9.1) and galectin (6.8) (Figure 5B). Adhesion pathways ranked far lower: ICAM contributed 0.84 and PECAM1 0.25.")

L("At the level of individual pairs, APP",
  "At the level of individual pairs, APP-CD74 (9.48), MIF-CD74-CD44 (7.29), MIF-CD74-CXCR4 (6.42) and COL4A2-CD44 (5.70) ranked highest, with HLA-B, HLA-A, HLA-C and HLA-E to CD8A immediately behind (4.87, 4.81, 4.67 and 3.99; Figure 5C). All values are summed dimensionless CellChat scores in arbitrary units, not probabilities.")

L("Two caveats apply. Both concern transcript abundance",
  "Two caveats apply. Both concern transcript abundance, not function. First, MHC class I ligand-receptor pairs dominate the pooled endothelial-to-T-cell ranking, and class II pairs are also present (aggregate score 6.3); CD8A is a co-receptor, and these data contain no peptide-loading, T-cell-receptor or spatial information, so the ranking does not establish antigen presentation. Second, MIF-CD74 signaling, described in review literature as suppressing CD8 effector function and favoring myeloid suppression [24], is the second strongest pooled endothelial output; these data cannot attribute MIF to an endothelial source in vivo or establish an immunosuppressive effect. Ligand-abundance ranks were identical across five independent down-sampling seeds (Table S8).",
  "results-caveats")

L("To place the four adjacent-normal libraries in context",
  "To place the four adjacent non-malignant libraries in context, we re-analysed three public single-cell datasets without additional experimentation. Across seven matched tumour/adjacent pairs from two independent ESCC cohorts, transferred venous fractions were higher in adjacent tissue in 7/7 pairs and interferon-responsive fractions were lower in adjacent tissue in 7/7 pairs (two-sided sign test, P = 0.0156; BH-adjusted q = 0.023 across three states); tip-like fractions were lower in adjacent tissue in 6/7 pairs (P = 0.125, q = 0.125). Because the expected directions were taken from the discovery cohort, these tests are descriptive rather than confirmatory. In a curated normal oesophago-gastric endothelial atlas (3,951 endothelial cells), venous cells were the largest author-annotated population (49.8% overall; 51.1% in normal donors). Absolute proportions were not reproducible across platforms: under the same label-transfer procedure, the venous fraction in adjacent-normal libraries ranged from 31.0% to 64.6% across external cohorts, compared with 77.7% in the discovery cohort (74.8% under its original manual annotation). Agreement between the two label-transfer methods was 48.8%. These analyses are directional and exploratory; they do not provide independent histological, multiplex immunofluorescence or spatial validation of the endothelial states (Table S9, Figure S4).",
  "results-external")

L("Our contribution is a state-resolved description plus a methodological caution",
  "Our contribution is a state-resolved re-analysis plus a methodological caution, not a claim of first discovery or a new mechanism. Tumor-versus-adjacent differences in endothelial composition were already reported in the atlas that generated these data [13] and in later ESCC endothelial studies [15]. We add a finer transcriptional-state partition of the CD45-negative compartment, separate venous, tip-like, matrix-remodeling, inflamed-venule and interferon-responsive programs, and quantify how far the four adjacent libraries, the paired design and closure constrain the estimated differences. Based on four adjacent libraries, venous endothelium is less represented and tip-like and matrix-remodeling endothelium more represented in tumors; arterial endothelium holds steady. The tip-cell program combines reduced venous transcripts with a matrix-remodeling program built on collagens and matrix metalloproteinases, compatible with basement-membrane remodeling but not proof of it. A candidate interferon-responsive state expressing CXCL9, CXCL10 and CXCL11 adds an exploratory immune dimension to the same compositional difference.",
  "disc1")

L("The venous-to-tip exchange is the clearest result.",
  "The reciprocal compositional shift between venous and tip-like endothelial states is the clearest result. In adjacent mucosa most endothelial cells are venous and tip cells are essentially absent; among the 56 unmatched tumors the median venous fraction falls from 74.8% to 28.5% while tip-like cells account for 14.8% of endothelial cells. The arterial fraction does not move. Because these proportions sum to one, part of the inverse venous-tip relationship is a closure effect: a centered log-ratio transformation reduces the coefficient from -0.61 to -0.46, and a Dirichlet-multinomial null model that preserves the observed cell counts produces a median of -0.25. The observed shift exceeds that null (empirical P = 0.0005-0.0062), but we do not interpret it as proof of a phenotypic switch or of absolute venous cell loss; it is a change in relative representation and is consistent with the tip-cell enrichment reported across tumor types [10].",
  "disc2")

L("The interferon-responsive subset is the most interesting population for immunotherapy.",
  "The candidate interferon-responsive state is of interest for immunotherapy but is not established here as an independent endothelial subtype. It expresses CXCL9, CXCL10 and CXCL11, which recruit CXCR3-expressing CD8 T cells in experimental systems [28], and is largely absent from adjacent mucosa. Its prevalence varies more than tenfold between tumors and does not track stage. Stability is weaker than for the venous and tip-like differences: only one adjacent library contained this state, equal-cell-count down-sampling retained its corrected difference in 16% and 85.5% of replicates at 20 and 30 cells per sample, the four paired tumors gave inconsistent directions, agreement between two label-transfer methods was 48.8%, and marker-level support reversed in GSE203067 (Tables S9, S11, S12). Whether this state relates to benefit from PD-1 blockade is a hypothesis only; an interferon-gamma-related expression profile has been proposed as a predictive biomarker in pembrolizumab-treated cohorts, with the authors cautioning that such a signature is necessary but not always sufficient [29], and no immunotherapy cohort is available here. The nominal association with exhaustion-marker-high CD8 cells did not survive correction across the nine states (smallest FDR = 0.16), arterial endothelium showed a similar coefficient, and the stronger result was confined to a post hoc 47-sample subset. We therefore do not advance a recruit-then-disable interpretation.",
  "disc-ifn")

L("The communication analysis produced a result we did not anticipate.",
  "The communication analysis produced a ranking we did not anticipate. We had assumed, from the literature on leukocyte homing, that adhesion molecules would dominate endothelial output. CellChat ranked MHC class I first and MIF second by ligand transcript abundance, with ICAM and PECAM1 contributing less than 3% of the total. This is a pooled transcript-level result: tumor and adjacent-normal cells from different patients were combined, so a ligand detected in one patient's endothelium and a receptor detected in another patient's T cells may be paired by the model without those cells sharing a tissue microenvironment. The ranking cannot show whether T-cell entry is limiting in these tumours, whether any interaction is tumour-specific, or whether antigen presentation occurs; lower adhesion ranks may simply reflect lower ICAM1 and PECAM1 transcript abundance relative to MHC class I ligands. Neutralizing the endothelin B receptor relieved an endothelial barrier and increased T-cell homing through an ICAM-1-dependent mechanism in an experimental model [30]. Reviews have described endothelial cells as amateur antigen-presenting cells [31] and proposed tumor endothelial cells as immune directors of the microenvironment [32], and mouse or ex vivo studies link lymphatic MHC class II signaling [33] and liver sinusoidal cross-presentation [34] to immunosuppression or tolerance. CD8A is a co-receptor and these data contain no peptide-loading, T-cell-receptor or spatial information, so which outcome, if any, dominates in ESCC cannot be settled here. The mechanistic statements in this paragraph derive from reviews [31, 32] and from mouse or ex vivo models [30, 33, 34]; none was tested in our cohort.",
  "disc-cellchat")

L("Transcripts encoding MIF",
  "Transcripts encoding MIF-CD74 axis components are abundant in this pooled analysis, which is consistent with, but does not establish, an immunosuppressive role. MIF binds CD74, which forms a functional complex with CXCR4 in biochemical experiments [35]; CD44 has also been implicated in this receptor complex and, as reviewed elsewhere, the MIF-CD74 axis suppresses CD8 effector function and promotes myeloid suppression [24]. In ESCC, high MIF expression in tumor cells and in tumor-infiltrating lymphocytes has been associated with poor survival [36]. A 2026 Theranostics study integrated seven single-cell datasets from 192 ESCC patients (including GSE160269) with spatial transcriptomics and multiplex immunohistochemistry, and proposed that MIF-high, cholesterol-biosynthetic tumor cells disrupt germinal-center B-cell reactions within tertiary lymphoid structures through MIF-CXCR4 competition with CXCL12-CXCR4 [37]. That study concerns a tumor-cell ligand source and a B-cell target in tertiary lymphoid structures; our result is a pooled transcript-level ligand-receptor expression ranking across endothelial and T cells. The two are not in conflict, but our data cannot extend the tumor-cell mechanism to endothelium: the cellular source and functional consequences of endothelial-associated MIF signaling remain unresolved in our dataset. The prominence of MIF here, together with the high proportion of exhaustion-marker-high CD8 T cells (35.8% of all 69,278 T cells met our marker-detection definition, characterized by multiple inhibitory-receptor transcripts [38]; this dataset-level fraction uses all T cells as its denominator, whereas the patient-level exhaustion variable used the proportion of CD8 T cells carrying at least two exhaustion-associated markers), is consistent with, but does not establish, a contribution of the endothelium to that phenotype.",
  "disc-mif")

L("Sample size and patient-level precision.",
  "Sample size and patient-level precision. The dataset contains only four adjacent non-malignant libraries, contributing 856 endothelial cells (9.0% of the analyzed compartment); comparisons between tumor and adjacent states are exploratory. Four of the 60 tumors came from the same four patients, so the primary comparison used 56 unmatched tumors and four adjacent libraries with an exact rank-sum test and BH correction across nine states; the four pairs were reported as directions only, and the pooled 60-versus-4 comparison as a sensitivity analysis. With four pairs, the smallest attainable two-sided P value for a paired sign test is 0.125, so a paired design has no power here. Cell numbers per patient were modest (median 106 endothelial cells, interquartile range 36-216; 13 of 60 tumors contributed fewer than 30), so state proportions for individual patients are imprecise. In 200 repeated equal-cell-count down-sampling experiments at 20 or 30 endothelial cells per sample under the primary design, venous, tip-like and matrix-remodeling differences survived correction in at least 99.5% of replicates, whereas the interferon-responsive difference survived in 16% and 85.5% of replicates. The bootstrap confidence intervals assume the four adjacent libraries are exchangeable draws from one population; with four libraries this assumption cannot be verified and the intervals should not be read as precise population estimates. Retaining the 529-cell fibroblast-like cluster changed the principal median differences by at most 1.9 percentage points and preserved their directions; the capillary judgement sits at the 0.05 boundary and is not stable to the exact test, to cluster retention, or to the choice of primary design (Tables S11, S12).",
  "lim1")

L("Compositional and analytical constraints.",
  "Compositional and analytical constraints. State proportions are compositional: they sum to one, so negative correlations between states arise mechanically. The observed venous-tip coefficient of -0.61 fell to -0.46 after a centered log-ratio transformation, and Dirichlet-multinomial null models that preserve closure and the observed cell counts generated a median coefficient of -0.25 to -0.28. The shift exceeds that null (empirical P = 0.0005-0.0062) but is smaller than the raw coefficient suggests, and we no longer describe it as evidence of a specific phenotypic switch. Clustering was also resolution-dependent: at resolutions 0.4, 0.6 and 0.8 the adjusted Rand index against the nine-state annotation fell from 0.80 to 0.68 to 0.52 (Table S8). We did not test endothelial-to-mesenchymal transition directly [42]; endothelial identity markers were retained in all states, but a partial shift in a subset of cells cannot be excluded. State assignment relied on marker expression and manual inspection. Two independent references (SingleR against Blueprint ENCODE, and CellMarker marker-set projection; Figure S1) supported endothelial identity for all nine states, but neither reference contains tumor-associated subsets such as tip, matrix-associated or interferon-responsive endothelium. The communication analysis used 50 permutations in the primary run and 200 permutations in two robustness runs; even at 200 permutations most retained pairs have P = 0 and all survive Benjamini-Hochberg correction, so the list should be read as expressed ligand-receptor pairs; individual pairs are not supported as statistically significant (Table S8). CellChat ranks pairs by ligand abundance and contains no peptide-loading, T-cell-receptor or spatial information, so it cannot establish antigen presentation. Tumour-derived and adjacent-normal cells, and cells from different patients, were pooled in a single communication object, so the ranking is a pooled transcript-level expression landscape and is neither tumour-specific nor evidence that a ligand and receptor co-occurred in one patient's tissue. The state labels are transcriptional descriptors: 'interferon-responsive' does not distinguish type I from type II interferon signaling, 'candidate' reflects the limited stability of that state, and 'tip-like' does not establish a migratory or sprouting phenotype.",
  "lim2")

L("External and clinical limitations.",
  "External and clinical limitations. The external single-cell resources were derived from stomach and oesophago-gastric junction tissue, including benign metaplastic and inflammatory conditions, and do not substitute for additional paired ESCC adjacent-normal samples; the discovery cohort still contains four such libraries. Background marker positivity ranged from 19.8% to 93.2% across cohorts and states, and marker-level support for the interferon-responsive state ran in the opposite direction in GSE203067; the two label-transfer methods agreed for only 48.8% of cells, so the external comparison is directional only. The 2026 Theranostics study [37] supplies spatial and multiplex immunohistochemistry evidence for a tumor-cell MIF source, but not for endothelial MIF, and no orthogonal protein-level, spatial or histological validation of the nine endothelial states was performed here. The external prognostic cohort contained 32 events and violated the proportional-hazards assumption, so a modest effect cannot be excluded and its hazard ratio is not interpretable as a constant effect; the score was developed on microarray data and applied to RNA-seq data, and absolute values are not comparable across platforms. Finally, clinical annotation was limited to stage and T/N/M; age, sex and survival were not released, no cohort with immunotherapy or anti-angiogenic treatment endpoints was available, and no independent paired ESCC adjacent-normal cohort was analysed.",
  "lim3")

L("Based on four adjacent-normal libraries, ESCC tumors and adjacent mucosa differ",
  "Based on four adjacent non-malignant libraries, and with a primary comparison restricted to the 56 unmatched tumors, ESCC tumors and adjacent mucosa differ in endothelial state composition: venous endothelium is less represented, and tip-like and matrix-remodeling states are more represented in tumors. A candidate, exploratory interferon-responsive state expresses transcripts encoding CXCL9, CXCL10 and CXCL11 but is less stable than the venous and tip-like differences. A pooled transcript-level endothelial-to-T-cell ligand-receptor expression analysis ranks MHC class I and MIF highest, with adhesion molecules contributing far less; this ranking is not evidence of tumour-specific communication, antigen presentation or any other function. Tip-derived transcripts separate tumor from adjacent tissue, but so do matched random gene sets, and neither the score nor the state proportions predict survival. External cohorts support the direction of the compositional difference, but not the absolute proportions. A second cohort again showed no prognostic information. These observations are descriptive and hypothesis-generating. Establishing any role in immune stratification or in predicting response to anti-angiogenic therapy requires cohorts with treatment endpoints and orthogonal validation, which this study does not provide.",
  "conclusion")

L("All datasets analyzed in this study are publicly available.",
  "All datasets analyzed in this study are publicly available. Single-cell data were obtained from GSE160269, bulk cohorts from GSE53625, GSE20347 and GSE45670, and the chemotherapy validation cohort from GSE225178 (Gene Expression Omnibus, https://www.ncbi.nlm.nih.gov/geo/). Three further public single-cell resources were used for directional external support: GSE196756 [43], GSE203067 [44] and the CELLxGENE endothelial subset of the Nowicki-Osuch gastrointestinal atlas [45]; processed target-gene matrices, state centroids and all numerical outputs are in Supplementary Table S9. For the cross-platform prognostic re-check, TCGA-ESCA expression, clinical and survival files were obtained from UCSC Xena (tcga.xenahubs.net); the underlying TCGA esophageal carcinoma cohort is described elsewhere [46], and the re-check outputs are in Supplementary Table S10. All numerical outputs are contained in the article and its Supplementary Material (Tables S1-S12, Figures S1-S4); Table S12 documents the paired/unpaired statistical redesign, the exact-test comparison and the code inventory. Analysis scripts and processed objects are available from the corresponding author on reasonable request; further inquiries can be directed to the corresponding author.",
  "data-availability")

L("The authors used a generative artificial intelligence assistant",
  "The authors used a generative artificial intelligence assistant (Tencent Hunyuan, model identifier Hy, developed by Tencent and accessed through the WorkBuddy desktop application, workbuddy.cn; the interface did not expose a numeric model version; accessed between 2 and 9 November 2026) to assist with language editing, drafting of the manuscript text and formatting of tables and figure legends; the tool was not used to generate data, statistical results, images or references, all analyses were performed by the authors with the software specified in Materials and methods, every AI-assisted passage was verified against the underlying analysis outputs and the cited literature, and the authors take full responsibility for the accuracy, originality and integrity of the content.",
  "ai-disclosure")

L("The Supplementary Material for this article comprises:",
  "The Supplementary Material for this article comprises: Table S1 (quality-control metrics per library), Table S2 (marker genes of the nine endothelial states), Table S3 (differential expression, tip versus venous endothelium), Table S4 (differential expression, tip versus capillary endothelium), Table S5 (differential expression, interferon-responsive versus venous endothelium), Table S6 (matrix-associated versus venous endothelium), Table S7 (all retained ligand-receptor pairs from CellChat), Table S8 (reproducibility and robustness: software versions, random seeds, resolution sensitivity, compositional null models, down-sampling, matched random-gene controls, permutation controls, proportional-hazards check and revised correlation tables), Table S9 (external single-cell directional validation, including paired sign tests, marker expression, label-transfer agreement and threshold sensitivity), Table S10 (cross-platform prognostic re-check, including both standardization conventions, all Cox models and random-gene null distributions), Table S11 (leave-one-adjacent-normal-out, cluster-retention, exact-test, Hodges-Lehmann effect-size and bootstrap sensitivity analyses) and Table S12 (paired/unpaired statistical redesign: sample-pairing map, primary 56-versus-4 exact tests, four paired directions, pooled 60-versus-4 sensitivity, leave-one-out BH families, exact-versus-asymptotic comparison, equal-cell-count down-sampling and the analysis-code inventory). Figure S1 (reference-based annotation check), Figure S2 (endothelial state fractions and CD8 exhaustion), Figure S3 (tip signature and response to neoadjuvant chemotherapy) and Figure S4 (external single-cell validation) are provided as separate image files. Each table is also supplied as a standalone file.",
  "supplementary")

L("**Figure 2. Compositional remodeling.**",
  "**Figure 2. Endothelial-state composition.** **(A)** Composition of all 60 tumors, ordered by descending venous fraction. **(B)** Fractions of the six principal states in the 56 unmatched tumors and four adjacent non-malignant libraries used for the primary comparison; boxes show median and interquartile range, whiskers extend to 1.5 times the interquartile range. **(C)** Median fractions across states for the same comparison. The four paired tumors are not included in (B) or (C); their paired directions and the pooled 60-versus-4 sensitivity analysis are in Table S12.",
  "fig2")

L("**Figure 4. Interferon-responsive endothelium.**",
  "**Figure 4. Candidate interferon-responsive endothelium.** **(A)** Expression of inflammatory and antigen-presenting genes across states. **(B)** Gene Ontology enrichment of genes upregulated in this state relative to venous endothelium. **(C)** Fraction of interferon-responsive endothelial cells in individual tumors; the Y axis is the interferon-responsive fraction. This state is exploratory and its stability is lower than that of the venous and tip-like differences (Tables S9, S11, S12).",
  "fig4")

L("**Figure 5. Pooled endothelial-to-T-cell ligand-receptor expression.**",
  "**Figure 5. Pooled transcript-level endothelial-to-T-cell ligand-receptor expression.** **(A)** Number of retained expressed ligand-receptor pairs from each endothelial state to each of five interpretable T-cell groups; 2,109 T cells satisfying no marker rule (Other/unclassified T) were excluded from these summaries. **(B)** Aggregate CellChat score by pathway (summed dimensionless score, arbitrary units). Numbers at the ends of bars indicate how many ligand-receptor pairs contribute to each pathway. **(C)** Leading ligand-receptor pairs targeting CD8 T cells, colored by pathway. 'CD8 exhausted' denotes CD8 T cells expressing at least two exhaustion-associated markers, a transcriptional phenotype and not evidence of functional exhaustion. Tumour and adjacent-normal cells from different patients were pooled, so these are not tumour-specific or within-patient interactions. Adhesion ligands were less abundant than MHC class I transcripts (Table S8).",
  "fig5")

L("**Figure S4. External single-cell validation using public data only.**",
  "**Figure S4. External single-cell validation using public data only.** **(A)** Author annotation of a curated normal/benign oesophago-gastric endothelial atlas (CELLxGENE, n = 3,951 endothelial cells); red dashed line, median venous fraction (77.7%) in the four adjacent non-malignant libraries of the discovery cohort under the same label-transfer procedure (74.8% under its original manual annotation). **(B)** Fraction of endothelial cells expressing at least two markers of the tip-like or interferon-responsive state; background positivity ranged from 19.8% to 93.2% across cohorts and states, and marker-level support for the interferon-responsive state reversed direction in GSE203067. **(C)** Venous fraction after cross-dataset label transfer (exploratory; agreement between two transfer methods 48.8%). **(D)** Patient-level paired direction across seven tumour/adjacent pairs from two independent ESCC cohorts; two-sided sign test with BH correction across three states, with expected directions specified from the discovery cohort (Table S9). N, adjacent non-malignant mucosa; T, tumour. State names in the figure follow the display names used in Figures 1-5.",
  "figS4")

s = "\n".join(lines)

# ---------------------------------------------------------------- checks
def chk(cond, msg):
    if not cond:
        raise SystemExit("[CHECK FAIL] " + msg)


ab = s.split("## Abstract", 1)[1].split("**Keywords:**", 1)[0].strip()
words = re.findall(r"[A-Za-z0-9'’-]+", ab)
chk(len(words) <= 350, "abstract %d words > 350" % len(words))
for glued in ["9,531retained", "atpatient", "ninestates", "Theseobservations",
              "0.9998in", "Hodges-Lehmannvenous"]:
    chk(glued not in ab, "glued token in abstract: %s" % glued)
for junk in ["None of these studies compared", "venous depletion", "venous-to-tip exchange",
             "All 60 tumors and 4 adjacent samples entered the test",
             "5,758", "5,692", "significant interactions", "Total communication probability",
             "default CD4 T label", "35.8% of all 69,278 T cells met our marker-detection definition of exhausted CD8"]:
    chk(junk not in s, "stale text remains: %s" % junk)
body = s.split("## Introduction", 1)[1].split("## References", 1)[0]
nums = []
for m in re.finditer(r"\[(\d+(?:,\s*\d+)*)\]", body):
    for tok in m.group(1).split(","):
        nums.append(int(tok.strip()))
chk(max(nums) == 46, "citation max %d != 46" % max(nums))
chk(len(re.findall(r"(?m)^\d+\. ", s)) == 46, "reference count != 46")
chk("Tables S1-S12" in s, "S12 not declared in Data availability")
print("[OK] line edits: %d" % N[0])
print("[OK] abstract words = %d (limit 350)" % len(words))
print("[OK] citations 1..%d, references %d" % (max(nums), len(re.findall(r"(?m)^\d+\. ", s))))
print("[OK] table caption order:", [c[:11] for c in re.findall(r"(?m)^\*\*Table \d+\.", s)])

if "--apply" in sys.argv:
    io.open(PATH, "w", encoding="utf-8").write(s + "\n")
    print("[APPLIED]", PATH)
else:
    print("[DRY-RUN OK]")
